"""Command-line parsing and user-facing diagnostics."""
import os
import re
import sys
from dataclasses import dataclass, field


class Exit(Exception):
    def __init__(self, code=0, out='', err=''):
        self.code, self.out, self.err = code, out, err


@dataclass
class Options:
    directory: str = None
    depth: int = None
    max_depth: int = None
    no_extension: bool = False
    generate: str = None
    mkdir: bool = False
    map_file: str = None
    quiet: bool = False
    regex: str = None
    sort: str = None
    test: bool = False
    overwrite: bool = False
    positional: list = field(default_factory=list)


# name, short option, field, metavar, aliases, description
SPECS = [
    ('dir', 'd', 'directory', 'PATH', (), 'Sets the working directory'),
    ('depth', None, 'depth', 'DEPTH', (), "Optional value to overwrite inferred subdirectory depth value in 'regex' mode"),
    ('no-extension', 'E', 'no_extension', None, (), "Does not preserve the extension of input files in 'sort' and 'regex' options"),
    ('generate', 'g', 'generate', 'PATH', (), "Stores a JSON map file in '<PATH>' after renaming files"),
    ('help', 'h', 'help', None, (), 'Print help'),
    ('mkdir', 'k', 'mkdir', None, (), "Recursively creates all parent directories of '<OUTPUT>' if they are missing"),
    ('map', 'm', 'map_file', 'PATH', ('from-file',), 'Sets the path of map file to be used for renaming files'),
    ('max-depth', None, 'max_depth', 'DEPTH', (), "Optional value to set the maximum of subdirectory depth value in 'regex' mode"),
    ('quiet', 'q', 'quiet', None, (), 'Does not print the map table to stdout'),
    ('regex', 'r', 'regex', 'PATTERN', (), 'Regex pattern to match by filenames'),
    ('sort', 's', 'sort', 'ORDER', (), 'Sets the order of natural sorting (by name) to rename files using enumerator'),
    ('test', 't', 'test', None, ('dry-run',), 'Runs in test mode without renaming actual files'),
    ('version', 'V', 'version', None, (), 'Print version'),
    ('overwrite', 'w', 'overwrite', None, (), "Overwrites output files, otherwise, a '_' is prepended to filename"),
]
LONG = {s[0]: s for s in SPECS}
for _s in SPECS:
    for _alias in _s[4]:
        LONG[_alias] = _s
SHORT = {s[1]: s for s in SPECS if s[1]}
ARG_DESC = ('OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern '
            'to match by filenames. SOURCE has the same function as -r option')
FOOTER = ("OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is the captured "
          "group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino "
          'for more information.')
MORE = "For more information, try '--help'.\n"


def opt_label(spec):
    return '--' + spec[0] + ((' <' + spec[3] + '>') if spec[3] else '')


def help_text(prog, long=False):
    lines = ['Batch rename utility for developers', '',
             'Usage: ' + prog + ' [OPTIONS] [[SOURCE] OUTPUT]...', '', 'Arguments:']
    if long:
        lines += ['  [[SOURCE] OUTPUT]...', '          ' + ARG_DESC]
    else:
        lines += ['  [[SOURCE] OUTPUT]...  ' + ARG_DESC]
    lines += ['', 'Options:']
    for spec in SPECS:
        name, short, fieldname, meta, aliases, description = spec
        left = ('  -' + short + ', ' if short else '      ') + opt_label(spec)
        if name == 'help':
            description += " (see a summary with '-h')" if long else " (see more with '--help')"
        if long:
            lines += [left, '          ' + description]
            if aliases:
                lines += ['          ', '          [aliases: ' + ', '.join('--' + a for a in aliases) + ']']
            if name == 'sort':
                lines += ['', '          Possible values:',
                          '          - asc:  Sort in ascending order',
                          '          - desc: Sort in descending order']
            lines += ['']
        else:
            if aliases:
                description += ' [aliases: ' + ', '.join('--' + a for a in aliases) + ']'
            if name == 'sort':
                description += ' [possible values: asc, desc]'
            lines += [left.ljust(28) + description]
    if not long:
        lines += ['']
    lines += [FOOTER]
    return '\n'.join(lines) + '\n'


def similarity(a, b):
    """Jaro-Winkler similarity, used only to offer spelling suggestions."""
    if a == b:
        return 1.0
    radius = max(len(a), len(b)) // 2 - 1
    radius = max(0, radius)
    aa, bb = [False] * len(a), [False] * len(b)
    for i, c in enumerate(a):
        for j in range(max(0, i-radius), min(len(b), i+radius+1)):
            if not bb[j] and c == b[j]:
                aa[i] = bb[j] = True
                break
    n = sum(aa)
    if not n:
        return 0.0
    x = [c for c, match in zip(a, aa) if match]
    y = [c for c, match in zip(b, bb) if match]
    transpositions = sum(c != d for c, d in zip(x, y)) / 2
    jaro = (n / len(a) + n / len(b) + (n-transpositions)/n) / 3
    common = 0
    for c, d in zip(a[:4], b[:4]):
        if c != d:
            break
        common += 1
    return jaro + common * 0.1 * (1-jaro) if jaro > 0.7 else jaro


def suggest(value, candidates):
    scored = [(similarity(value, cand), cand) for cand in candidates]
    if not scored:
        return None
    best = max(scored)
    return best[1] if best[0] > 0.8 else None


def parse(argv):
    prog = os.path.basename(argv[0]) or 'executable'
    args = argv[1:]
    options = Options()
    seen = []

    def usage(required=False, generic=False, extra=None):
        if generic:
            return f'Usage: {prog} [OPTIONS] [[SOURCE] OUTPUT]...'
        flags = seen[:]
        if extra and extra not in flags:
            flags.append(extra)
        bits = [opt_label(LONG[name]) for name in flags]
        if not bits and not options.positional and not required:
            bits.append('[OPTIONS]')
        bits.append('<[SOURCE] OUTPUT>...' if required or options.positional else '[[SOURCE] OUTPUT]...')
        return 'Usage: ' + prog + ' ' + ' '.join(bits)

    def fail(message, usg=None):
        text = 'error: ' + message + '\n\n'
        if usg:
            text += usg + '\n\n'
        raise Exit(2, err=text + MORE)

    def missing(spec):
        message = f"a value is required for '{opt_label(spec)}' but none was supplied"
        if spec[0] == 'sort':
            message += '\n  [possible values: asc, desc]'
        fail(message)

    def unexpected(token, short=False):
        spelling = token.split('=', 1)[0] if token.startswith('--') else token
        candidate = suggest(spelling[2:], LONG) if spelling.startswith('--') else None
        msg = f"unexpected argument '{spelling}' found\n\n"
        if candidate:
            msg += f"  tip: a similar argument exists: '--{candidate}'"
            u = usage(extra=LONG[candidate][0])
        else:
            msg += f"  tip: to pass '{spelling}' as a value, use '-- {spelling}'"
            u = usage(generic=short)
        fail(msg, u)

    def put(spec, value, longform=False):
        name, short, fieldname, meta, aliases, desc = spec
        if name in seen:
            fail(f"the argument '{opt_label(spec)}' cannot be used multiple times", usage(generic=True))
        if not meta and value is not None:
            fail(f"unexpected value '{value}' for '{opt_label(spec)}' found; no more were expected", usage(extra=name))
        if name == 'help':
            raise Exit(out=help_text(prog, long=longform))
        if name == 'version':
            raise Exit(out='nomino 1.6.4\n')
        if meta:
            if value is None or (value == '' and name in ('dir', 'generate', 'map', 'sort')):
                missing(spec)
            if name in ('depth', 'max-depth'):
                why = None
                if not value:
                    why = 'cannot parse integer from empty string'
                elif not re.fullmatch(r'\+?[0-9]+', value):
                    why = 'invalid digit found in string'
                elif len(value.lstrip('+0')) > 20 or int(value) > 18446744073709551615:
                    why = 'number too large to fit in target type'
                if why:
                    fail(f"invalid value '{value}' for '{opt_label(spec)}': {why}")
                value = int(value)
            elif name == 'sort':
                if value.lower() not in ('asc', 'desc'):
                    message = f"invalid value '{value}' for '{opt_label(spec)}'\n  [possible values: asc, desc]"
                    near = suggest(value, ('asc', 'desc'))
                    if near:
                        message += f"\n\n  tip: a similar value exists: '{near}'"
                    fail(message)
                value = value.lower()
        else:
            value = True
        seen.append(name)
        setattr(options, fieldname, value)

    i = 0
    positional_only = False
    while i < len(args):
        token = args[i]
        if positional_only or token == '-' or not token.startswith('-'):
            options.positional.append(token)
            i += 1
            continue
        if token == '--':
            positional_only = True
            i += 1
            continue
        if token.startswith('--'):
            label, sep, inline = token[2:].partition('=')
            if label not in LONG:
                unexpected(token)
            spec = LONG[label]
            if sep:
                put(spec, inline, True)
            elif spec[3]:
                if i+1 >= len(args):
                    put(spec, None, True)
                nxt = args[i+1]
                if nxt.startswith('-') and nxt != '-':
                    if nxt.startswith('--'):
                        if nxt != '--' and nxt[2:].split('=')[0] not in LONG:
                            unexpected(nxt)
                    elif len(nxt) > 1 and nxt[1] not in SHORT:
                        unexpected('-' + nxt[1], True)
                    missing(spec)
                i += 1
                put(spec, args[i], True)
            else:
                put(spec, None, True)
        else:
            j = 1
            while j < len(token):
                letter = token[j]
                if letter not in SHORT:
                    unexpected('-' + letter, True)
                spec = SHORT[letter]
                if spec[3]:
                    if j+1 < len(token):
                        value = token[j+1:]
                        if value.startswith('='):
                            value = value[1:]
                    else:
                        if i+1 >= len(args):
                            put(spec, None)
                        nxt = args[i+1]
                        if nxt.startswith('-') and nxt != '-':
                            if nxt.startswith('--'):
                                if nxt != '--' and nxt[2:].split('=')[0] not in LONG:
                                    unexpected(nxt)
                            elif len(nxt) > 1 and nxt[1] not in SHORT:
                                unexpected('-' + nxt[1], True)
                            missing(spec)
                        i += 1
                        value = args[i]
                    put(spec, value)
                    break
                put(spec, None)
                j += 1
        i += 1
    if options.regex is not None and not options.positional:
        fail('the following required arguments were not provided:\n  <[SOURCE] OUTPUT>...', usage(required=True))
    return options
PY
