"""Plain, left-aligned two-column tables with Unicode display widths."""
import re
import unicodedata


ANSI = re.compile(r'\x1b\[[0-?]*[ -/]*[@-~]')


def width(text):
    n = 0
    for char in ANSI.sub('', text):
        cat = unicodedata.category(char)
        if cat in ('Mn', 'Me', 'Cf'):
            continue
        if unicodedata.east_asian_width(char) in ('W', 'F') and cat != 'Cn':
            n += 2
        else:
            n += 1
    return n


def lines(text):
    # Similar to string lines: only newline and CRLF delimit records.
    if not text:
        return ['']
    result = text.split('\n')
    if result[-1] == '':
        result.pop()
    return [s[:-1] if s.endswith('\r') else s for s in result]


def format_table(mapping):
    if not mapping:
        return ''
    rows = [(['Input'], ['Output'])]
    for out in sorted(mapping):
        rows.append((lines(mapping[out]), lines(out)))
    widths = [max(width(s) for row in rows for s in row[c]) for c in (0, 1)]
    border = '+' + '+'.join('-'*(w+2) for w in widths) + '+\n'
    result = [border]
    for index, row in enumerate(rows):
        for line in range(max(map(len, row))):
            cells = [row[c][line] if line < len(row[c]) else '' for c in (0, 1)]
