"""Command-line parsing and user-facing diagnostics."""
import os
import re
import sys
from dataclasses import dataclass, field


class Exit(Exception):
    def __init__(self, code=0, out='', err=''):
        self.code, self.out, self.err = code, out, err


@dataclass
class Options:
    directory: str = None
    depth: int = None
    max_depth: int = None
    no_extension: bool = False
    generate: str = None
    mkdir: bool = False
    map_file: str = None
    quiet: bool = False
    regex: str = None
    sort: str = None
    test: bool = False
    overwrite: bool = False
    positional: list = field(default_factory=list)


# name, short option, field, metavar, aliases, description
SPECS = [
    ('dir', 'd', 'directory', 'PATH', (), 'Sets the working directory'),
    ('depth', None, 'depth', 'DEPTH', (), "Optional value to overwrite inferred subdirectory depth value in 'regex' mode"),
    ('no-extension', 'E', 'no_extension', None, (), "Does not preserve the extension of input files in 'sort' and 'regex' options"),
    ('generate', 'g', 'generate', 'PATH', (), "Stores a JSON map file in '<PATH>' after renaming files"),
    ('help', 'h', 'help', None, (), 'Print help'),
    ('mkdir', 'k', 'mkdir', None, (), "Recursively creates all parent directories of '<OUTPUT>' if they are missing"),
    ('map', 'm', 'map_file', 'PATH', ('from-file',), 'Sets the path of map file to be used for renaming files'),
    ('max-depth', None, 'max_depth', 'DEPTH', (), "Optional value to set the maximum of subdirectory depth value in 'regex' mode"),
    ('quiet', 'q', 'quiet', None, (), 'Does not print the map table to stdout'),
    ('regex', 'r', 'regex', 'PATTERN', (), 'Regex pattern to match by filenames'),
    ('sort', 's', 'sort', 'ORDER', (), 'Sets the order of natural sorting (by name) to rename files using enumerator'),
    ('test', 't', 'test', None, ('dry-run',), 'Runs in test mode without renaming actual files'),
    ('version', 'V', 'version', None, (), 'Print version'),
    ('overwrite', 'w', 'overwrite', None, (), "Overwrites output files, otherwise, a '_' is prepended to filename"),
]
LONG = {s[0]: s for s in SPECS}
for _s in SPECS:
    for _alias in _s[4]:
        LONG[_alias] = _s
SHORT = {s[1]: s for s in SPECS if s[1]}
ARG_DESC = ('OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern '
            'to match by filenames. SOURCE has the same function as -r option')
FOOTER = ("OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is the captured "
          "group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino "
          'for more information.')
MORE = "For more information, try '--help'.\n"


def opt_label(spec):
    return '--' + spec[0] + ((' <' + spec[3] + '>') if spec[3] else '')


def help_text(prog, long=False):
    lines = ['Batch rename utility for developers', '',
             'Usage: ' + prog + ' [OPTIONS] [[SOURCE] OUTPUT]...', '', 'Arguments:']
    if long:
        lines += ['  [[SOURCE] OUTPUT]...', '          ' + ARG_DESC]
    else:
        lines += ['  [[SOURCE] OUTPUT]...  ' + ARG_DESC]
    lines += ['', 'Options:']
    for spec in SPECS:
        name, short, fieldname, meta, aliases, description = spec
        left = ('  -' + short + ', ' if short else '      ') + opt_label(spec)
        if name == 'help':
            description += " (see a summary with '-h')" if long else " (see more with '--help')"
        if long:
            lines += [left, '          ' + description]
            if aliases:
                lines += ['          ', '          [aliases: ' + ', '.join('--' + a for a in aliases) + ']']
            if name == 'sort':
                lines += ['', '          Possible values:',
                          '          - asc:  Sort in ascending order',
                          '          - desc: Sort in descending order']
            lines += ['']
        else:
            if aliases:
                description += ' [aliases: ' + ', '.join('--' + a for a in aliases) + ']'
            if name == 'sort':
                description += ' [possible values: asc, desc]'
            lines += [left.ljust(28) + description]
    if not long:
        lines += ['']
    lines += [FOOTER]
    return '\n'.join(lines) + '\n'


def similarity(a, b):
    """Jaro-Winkler similarity, used only to offer spelling suggestions."""
    if a == b:
        return 1.0
    radius = max(len(a), len(b)) // 2 - 1
    radius = max(0, radius)
    aa, bb = [False] * len(a), [False] * len(b)
    for i, c in enumerate(a):
        for j in range(max(0, i-radius), min(len(b), i+radius+1)):
            if not bb[j] and c == b[j]:
                aa[i] = bb[j] = True
                break
    n = sum(aa)
    if not n:
        return 0.0
    x = [c for c, match in zip(a, aa) if match]
    y = [c for c, match in zip(b, bb) if match]
    transpositions = sum(c != d for c, d in zip(x, y)) / 2
    jaro = (n / len(a) + n / len(b) + (n-transpositions)/n) / 3
    common = 0
    for c, d in zip(a[:4], b[:4]):
        if c != d:
