        if generic:
            return f'Usage: {prog} [OPTIONS] [[SOURCE] OUTPUT]...'
        flags = seen[:]
        if extra and extra not in flags:
            flags.append(extra)
        bits = [opt_label(LONG[name]) for name in flags]
        if not bits and not options.positional and not required:
            bits.append('[OPTIONS]')
        bits.append('<[SOURCE] OUTPUT>...' if required or options.positional else '[[SOURCE] OUTPUT]...')
        return 'Usage: ' + prog + ' ' + ' '.join(bits)

    def fail(message, usg=None):
        text = 'error: ' + message + '\n\n'
        if usg:
            text += usg + '\n\n'
        raise Exit(2, err=text + MORE)

    def missing(spec):
        message = f"a value is required for '{opt_label(spec)}' but none was supplied"
        if spec[0] == 'sort':
            message += '\n  [possible values: asc, desc]'
        fail(message)

    def unexpected(token, short=False):
        spelling = token.split('=', 1)[0] if token.startswith('--') else token
        candidate = suggest(spelling[2:], LONG) if spelling.startswith('--') else None
        msg = f"unexpected argument '{spelling}' found\n\n"
        if candidate:
            msg += f"  tip: a similar argument exists: '--{candidate}'"
            u = usage(extra=LONG[candidate][0])
        else:
            msg += f"  tip: to pass '{spelling}' as a value, use '-- {spelling}'"
            u = usage(generic=short)
        fail(msg, u)

    def put(spec, value, longform=False):
        name, short, fieldname, meta, aliases, desc = spec
        if name in seen:
            fail(f"the argument '{opt_label(spec)}' cannot be used multiple times", usage(generic=True))
        if not meta and value is not None:
            fail(f"unexpected value '{value}' for '{opt_label(spec)}' found; no more were expected", usage(extra=name))
        if name == 'help':
            raise Exit(out=help_text(prog, long=longform))
        if name == 'version':
            raise Exit(out='nomino 1.6.4\n')
        if meta:
            if value is None or (value == '' and name in ('dir', 'generate', 'map', 'sort')):
                missing(spec)
            if name in ('depth', 'max-depth'):
                why = None
                if not value:
                    why = 'cannot parse integer from empty string'
                elif not re.fullmatch(r'\+?[0-9]+', value):
                    why = 'invalid digit found in string'
                elif len(value.lstrip('+0')) > 20 or int(value) > 18446744073709551615:
                    why = 'number too large to fit in target type'
                if why:
                    fail(f"invalid value '{value}' for '{opt_label(spec)}': {why}")
                value = int(value)
            elif name == 'sort':
                if value.lower() not in ('asc', 'desc'):
                    message = f"invalid value '{value}' for '{opt_label(spec)}'\n  [possible values: asc, desc]"
                    near = suggest(value, ('asc', 'desc'))
                    if near:
                        message += f"\n\n  tip: a similar value exists: '{near}'"
                    fail(message)
                value = value.lower()
        else:
            value = True
        seen.append(name)
        setattr(options, fieldname, value)

    i = 0
    positional_only = False
    while i < len(args):
        token = args[i]
        if positional_only or token == '-' or not token.startswith('-'):
            options.positional.append(token)
            i += 1
            continue
        if token == '--':
            positional_only = True
            i += 1
            continue
        if token.startswith('--'):
            label, sep, inline = token[2:].partition('=')
            if label not in LONG:
