"""Output-pattern parser. Patterns are a sequence of literals and captures."""
import re


class FormatError(ValueError):
    pass


def unsigned(text):
    if not re.fullmatch(r'\+?[0-9]+', text):
        return None
    significant = text.lstrip('+0')
    if len(significant) > 20:
        return None
    value = int(text)
    return value if value <= 18446744073709551615 else None


class Formatter:
    def __init__(self, pattern):
        if pattern is None:
            raise FormatError('output formatter must be set')
        self.parts = []
        inside = False
        escape = False
        text = ''
        auto = 1
        for i, c in enumerate(pattern):
            if escape:
                if c not in '{}\\':
                    raise FormatError(f"invalid escape character of '{c}' at '{i}'")
                text += c
                escape = False
            elif c == '\\':
                escape = True
            elif c == '{' and not inside:
                self.parts.append(text)
                text = ''
                inside = True
            elif c == '}':
                if not inside:
                    raise FormatError("an unopened placeholder could not be closed by '}'")
                group, sep, padding = text.partition(':')
                if not group:
                    group = auto
                    auto += 1
                else:
                    numeric = unsigned(group)
                    if numeric is not None:
                        group = numeric
                width = None
                if sep and padding:
                    width = unsigned(padding)
                    if width is None:
                        raise FormatError(f"unable to parse padding of '{padding}'")
                self.parts.append((group, width))
                text = ''
                inside = False
            else:
                text += c
        if inside:
            raise FormatError("all opened placeholders must be closed by '}'")
        self.parts.append(text)

    def apply(self, captures, named=None):
        parts = []
        for part in self.parts:
            if isinstance(part, str):
                parts.append(part)
                continue
            group, width = part
            if isinstance(group, str):
                group = (named or {}).get(group, -1)
            value = captures[group] if 0 <= group < len(captures) else ''
            value = value or ''
            if width is not None:
                num = unsigned(value)
                if num is not None:
                    # Large widths are allowed; avoid integer format overflow on malformed input.
                    value = str(num).rjust(min(width, 10000000), '0')
            parts.append(value)
        return ''.join(parts)
