        elif not c.isalnum():
            char = c
        else:
            self.error('unrecognized escape sequence', start, 2)
        value = ord(char)
        return [(value, value)], value, None

    def char_class(self, flags):
        start = self.i
        self.i += 1
        self.skip(flags)
        negated = self.i < len(self.source) and self.source[self.i] == '^'
        if negated:
            self.i += 1
        initial_end = self.i
        first = True
        current = []
        accumulated = None
        operator = None
        while True:
            self.skip(flags)
            if self.i >= len(self.source):
                self.error('unclosed character class', start, initial_end-start)
            if self.source[self.i] == ']' and not first:
                self.i += 1
                break
            if not first and self.source[self.i:self.i+2] in ('&&', '--', '~~'):
                right = merge(current)
                if accumulated is None:
                    accumulated = right
                else:
                    accumulated = self.class_operation(accumulated, right, operator)
                operator = self.source[self.i:self.i+2]
                self.i += 2
                current = []
                continue
            unit_start = self.i
            ranges, literal = self.class_unit(flags)
            if first and literal == ord(']'):
                initial_end = self.i
            first = False
            self.skip(flags)
            if (self.i < len(self.source) and self.source[self.i] == '-' and
                    not self.source.startswith('--', self.i) and
                    self.i+1 < len(self.source) and self.source[self.i+1] != ']'):
                self.i += 1
                self.skip(flags)
                r, last = self.class_unit(flags)
                if literal is None or last is None:
                    self.error('invalid range boundary, must be a literal', unit_start, self.i-unit_start)
                if literal > last:
                    self.error('invalid character class range, the start must be <= the end', unit_start, self.i-unit_start)
                ranges = [(literal, last)]
            current.extend(ranges)
        result = merge(current)
        if accumulated is not None:
            result = self.class_operation(accumulated, result, operator)
        return inverse(result) if negated else result

    @staticmethod
    def class_operation(a, b, op):
        if op == '&&':
            return intersection(a, b)
        if op == '--':
            return subtract(a, b)
        if op == '~~':
            return merge(subtract(a, b) + subtract(b, a))
        return merge(a + b)

    def class_unit(self, flags):
        if self.i >= len(self.source):
            self.error('unclosed character class', max(0, self.i-1))
        c = self.source[self.i]
        if c == '[':
            posix = re.match(r'\[:(\^?)([a-z]+):\]', self.source[self.i:])
            if posix and posix.group(2) in POSIX:
                self.i += len(posix.group(0))
                ranges = POSIX[posix.group(2)]
                if posix.group(1):
                    ranges = inverse(ranges)
                return ranges, None
            return self.char_class(flags), None
        if c == '\\':
            ranges, value, expression = self.escape(flags, in_class=True)
            return ranges, value
        self.i += 1
        return [(ord(c), ord(c))], ord(c)

    def search(self, text):
        match = self.compiled.search(text)
        if match is None:
            return None
        return [match.group(i) for i in range(self.groups + 1)]
