"""Directory traversal, rename operations, and reversible map generation."""
import errno
import functools
import json
import os
import sys

from cli import Exit
from formatter import Formatter, FormatError
from regex_engine import Regex, RegexError
from table import format_table
from map_file import load_map


def os_error(exc):
    code = exc.errno if isinstance(exc, OSError) else errno.EINVAL
    if code is None:
        code = errno.EINVAL
    # Linux sometimes returns ENOTEMPTY while the CLI reports the portable
    # 'already exists' category for a nonempty directory destination.
    if code == errno.ENOTEMPTY:
        code = errno.EEXIST
    return f'{os.strerror(code)} (os error {code})'


def lossy(s):
    return os.fsencode(s).decode('utf-8', 'replace')


def natural_compare(a, b):
    i = j = 0
    while True:
        while i < len(a) and a[i].isspace():
            i += 1
        while j < len(b) and b[j].isspace():
            j += 1
        if i == len(a) or j == len(b):
            return (i < len(a)) - (j < len(b))
        ca, cb = a[i], b[j]
        if '0' <= ca <= '9' and '0' <= cb <= '9':
            ia, jb = i, j
            while i < len(a) and '0' <= a[i] <= '9':
                i += 1
            while j < len(b) and '0' <= b[j] <= '9':
                j += 1
            aa, bb = a[ia:i], b[jb:j]
            if ca == '0' or cb == '0':
                result = (aa > bb) - (aa < bb)
            else:
                result = (len(aa) > len(bb)) - (len(aa) < len(bb))
                if not result:
                    result = (aa > bb) - (aa < bb)
            if result:
                return result
            continue
        if ca != cb:
            return (ca > cb) - (ca < cb)
        i += 1
        j += 1


def walk(minimum, maximum):
    """Snapshot a depth-first traversal, without following directory symlinks."""
    result = []
    if minimum == 0:
        result.append('')
    if maximum == 0:
        return result

    def descend(path, depth):
        try:
            entries = list(os.scandir(path or '.'))
        except OSError:
            return
        for entry in entries:
            name = entry.name if not path else path + '/' + entry.name
            if depth >= minimum:
                result.append(name)
            if depth < maximum:
                try:
                    is_dir = entry.is_dir(follow_symlinks=False)
                except OSError:
                    is_dir = False
                if is_dir:
                    descend(name, depth+1)
    descend('', 1)
    return result


def extension(path):
    name = path.rstrip('/').rsplit('/', 1)[-1]
    if name in ('.', '..') or '.' not in name:
        return ''
    base, ext = name.rsplit('.', 1)
    return '.' + ext if base else ''


def normalized_parts(path):
    """Path components for replacing just the final filename on collision."""
    absolute = path.startswith('/')
    leading_dot = path.startswith('./') or path == '.'
    parts = [p for p in path.split('/') if p and p != '.']
    prefix = '/' if absolute else './' if leading_dot else ''
    return prefix, parts


def prepend_underscore(path):
    prefix, parts = normalized_parts(path)
    if parts and parts[-1] != '..':
        parts[-1] = '_' + parts[-1]
    else:
        parts.append('_')
    return prefix + '/'.join(parts)


def exists(path):
    try:
        return os.path.exists(path)
    except (ValueError, OSError):
        return False


class Renamer:
    def __init__(self, options):
        self.options = options
        self.mapping = {}
        self.failed = False

    def rename(self, source, target):
        opts = self.options
        # The displayed paths and the identity check are strings, not inode or
        # canonical-path comparisons.
        original = lossy(source)
        if original != target:
            if not opts.overwrite:
                while exists(target):
                    target = prepend_underscore(target)
            if opts.mkdir:
                parent = os.path.dirname(target)
                if parent:
                    try:
                        os.makedirs(parent, exist_ok=True)
                    except (OSError, ValueError):
                        pass
            if not opts.test:
                try:
                    os.rename(source, target)
                except (OSError, ValueError) as exc:
                    sys.stderr.write(f"[error] unable to rename '{original}': {os_error(exc)}\n")
                    self.failed = True
                    return
        self.mapping[target] = original

    def execute(self, argv0):
        opts = self.options
        if opts.directory is not None:
            try:
                os.chdir(opts.directory)
            except (OSError, ValueError) as exc:
                raise Exit(1, err='error: ' + os_error(exc) + '\n')
        output = opts.positional[-1] if opts.positional else None
        source = opts.positional[-2] if len(opts.positional) >= 2 else None
        if source is not None:
            if opts.regex is not None or opts.sort is not None or opts.map_file is not None:
                raise Exit(1, err='error: optional SOURCE must be used without setting regex, map or sort flags\n')
            regex = source
        else:
            regex = opts.regex
        try:
            if regex is not None:
                pattern = Regex(regex)
                formatter = Formatter(output)
                minimum = opts.depth if opts.depth is not None else regex.count('/')+1
                maximum = opts.max_depth if opts.max_depth is not None else minimum
                minimum = min(minimum, maximum)
                for path in walk(minimum, maximum):
                    captures = pattern.search(lossy(path))
                    if captures is not None:
                        target = formatter.apply(captures, pattern.names)
                        if not opts.no_extension:
                            target += extension(lossy(path))
                        self.rename(path, target)
            elif opts.sort is not None:
                formatter = Formatter(output)
                entries = [entry.name for entry in os.scandir('.')]
                entries.sort(key=functools.cmp_to_key(natural_compare), reverse=opts.sort == 'desc')
                for n, path in enumerate(entries, 1):
                    target = formatter.apply([lossy(path), str(n)])
                    if not opts.no_extension:
                        target += extension(lossy(path))
                    self.rename(path, target)
            elif opts.map_file is not None:
                mapping = load_map(opts.map_file)
                for path, target in mapping.items():
                    self.rename(path, target)
            else:
                raise Exit(1, err=("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\n"
                                   f"usage: run '{argv0} --help' for more information.\n"))
        except FormatError as exc:
            raise Exit(1, err='error: [output-format] ' + str(exc) + '\n')
        except RegexError as exc:
            raise Exit(1, err='error: ' + str(exc) + '\n')
        except OSError as exc:
            raise Exit(1, err='error: ' + os_error(exc) + '\n')
        if opts.generate is not None:
            try:
                with open(opts.generate, 'w', encoding='utf-8', newline='') as stream:
                    json.dump(self.mapping, stream, ensure_ascii=False, indent=2, sort_keys=True)
            except (OSError, ValueError) as exc:
                raise Exit(1, err='error: ' + os_error(exc) + '\n')
        if not opts.quiet:
            sys.stdout.write(format_table(self.mapping))
        return 1 if self.failed else 0
