import functools
import re
import unicodedata


class RegexError(ValueError):
    pass


def merge(ranges):
    out = []
    for lo, hi in sorted(ranges):
        if out and lo <= out[-1][1] + 1:
            out[-1] = (out[-1][0], max(hi, out[-1][1]))
        else:
            out.append((lo, hi))
    return out


def intersection(a, b):
    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        lo, hi = max(a[i][0], b[j][0]), min(a[i][1], b[j][1])
        if lo <= hi:
            out.append((lo, hi))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return out


def inverse(a, maximum=0x10ffff):
    out = []
    lo = 0
    for first, last in merge(a):
        if first > lo:
            out.append((lo, min(maximum, first-1)))
        lo = last + 1
        if lo > maximum:
            break
    if lo <= maximum:
        out.append((lo, maximum))
    return out


def subtract(a, b):
    return intersection(a, inverse(b))


def charset(ranges):
    if not ranges:
        return r'(?!)'

    def esc(n):
        if n <= 255:
            return r'\x%02x' % n
        if n <= 65535:
