            end = max(points)
            underline = ''.join('^' if i in points else ' ' for i in range(end+1))
            text = 'regex parse error:\n    ' + source + '\n    ' + underline
        else:
            ruler = '~'*79
            text = 'regex parse error:\n' + ruler
            start_line = 0
            source_lines = source.split('\n')
            digits = len(str(len(source_lines)))
            for lineno, line in enumerate(source_lines, 1):
                text += '\n' + str(lineno).rjust(digits) + ': ' + line
                marks = [p-start_line for p in points if start_line <= p <= start_line+len(line)]
                if marks:
                    text += '\n' + ' '*(digits+2) + ''.join('^' if k in marks else ' ' for k in range(max(marks)+1))
                start_line += len(line)+1
            text += '\n' + ruler
        raise RegexError(text + '\nerror: ' + message)

