            ranges, value, expression = self.escape(flags, in_class=True)
            return ranges, value
        self.i += 1
        return [(ord(c), ord(c))], ord(c)

    def search(self, text):
        match = self.compiled.search(text)
        if match is None:
            return None
        return [match.group(i) for i in range(self.groups + 1)]
